$fail=0;function group(string $name,callable $fn){global $fail,$p;try{$fn();echo "GROUP PASS $name\n";}catch(Throwable $e){if($p->inTransaction())$p->rollBack();$fail++;echo "GROUP FAIL $name ".get_class($e).' '.$e->getMessage()."\n";}}
group('financial correction/full payment/idempotency',function()use($p,$s,$f,$actor){$sid=(int)$f['hall']['partial']['session'];$before=$s->account($sid);ck($before['paid_total']===100000&&$before['remaining_total']===90000,'actual partial and remaining discount');$old=rows($p,'SELECT * FROM settlement_records WHERE session_id=? ORDER BY id',[$sid]);$preview=$s->previewRemainingDiscountCorrection($sid,'fixed',25000,$actor);$r=$s->adjustRemainingDiscount($sid,'fixed',25000,$preview['expected_signature'],'QA synthetic correction','qa-fp2-discount-correct',$actor);$a=$s->account($sid);ck($a['remaining_total']===75000&&$a['paid_total']===100000,'correct only unpaid portion');ck($old===rows($p,'SELECT * FROM settlement_records WHERE session_id=? ORDER BY id',[$sid]),'prior receipts unchanged');$args=['session_id'=>$sid,'expected_session_id'=>$sid,'expected_remaining_total'=>$a['remaining_total'],'expected_signature'=>$a['signature'],'mode'=>'full','destination'=>'direct','request_id'=>'qa-fp2-full-payment','print_receipt'=>false,'tenders'=>[['type'=>'cash','amount'=>75000]]];$p->beginTransaction();$r=$s->settle($args,$actor);ck((int)($r['settlement_id']??0)>0,'transactional final payment');$p->rollBack();ck($old===rows($p,'SELECT * FROM settlement_records WHERE session_id=? ORDER BY id',[$sid]),'rollback preserves prior receipts');$a=$s->account($sid);ck($a['remaining_total']===75000,'rollback preserves balance');$r=$s->settle($args,$actor);$rr=$s->settle($args,$actor);ck((int)$r['settlement_id']===(int)$rr['settlement_id'],'payment replay same record');ck((int)one($p,'SELECT COUNT(*) FROM settlement_records WHERE request_id=?',['qa-fp2-full-payment'])===1,'one durable payment');});
group('real order consumption and cancellation',function()use($p,$c,$clock,$actor,$item){$p->prepare("INSERT INTO inventory_items(item_code,name,base_unit,active) VALUES('qa-fp2-stock','QA ingredient','g',1)")->execute();$inv=(int)$p->lastInsertId();$p->prepare("INSERT INTO inventory_balances(inventory_item_id,quantity_base,average_unit_cost,cost_status) VALUES(?,1000,10,'known')")->execute([$inv]);$st=$p->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach(['module.inventory.enabled'=>'1','inventory_initialized'=>'1','inventory_reconciliation_required'=>'0'] as $k=>$v)$st->execute([$k,$v]);$c->inventoryOrders()->saveRecipe($item,[['inventory_item_id'=>$inv,'quantity_base'=>50]],$actor);[$t,$sid]=createSession($p,$clock,201);$oid=insertOrder($p,$clock,$t,$sid,$item,22001,2);$p->beginTransaction();$event=$c->inventoryOrders()->enqueueAccountedTx($oid,(int)$actor['id']);ck((int)$event>0,'durable consumption event');$p->commit();$balance=fn()=>(int)one($p,'SELECT quantity_base FROM inventory_balances WHERE inventory_item_id=?',[$inv]);ck($balance()===900,'exact material consumed');$args=['order_id'=>$oid,'request_id'=>'qa-fp2-cancel-order','reason'=>'QA cancelled'];$p->beginTransaction();$r=$c->orderStaffActions()->cancelWholeOrder($args,$actor);ck($balance()===1000,'material returned in transaction');$p->rollBack();ck($balance()===900&&one($p,'SELECT status FROM orders WHERE id=?',[$oid])==='accounted','rollback restores order and stock');$r=$c->orderStaffActions()->cancelWholeOrder($args,$actor);$rr=$c->orderStaffActions()->cancelWholeOrder($args,$actor);ck($balance()===1000&&($rr['idempotent']??false),'cancel and replay restore stock once');ck(one($p,'SELECT status FROM orders WHERE id=?',[$oid])==='cancelled','order cancelled');});
