fp2-history-'.$i);$p->prepare("UPDATE print_jobs SET status='submitted' WHERE id=?")->execute([(int)$x['job_id']]);}$p->commit();$m=$c->printManagement();$fa=strtr((string)$job,['0'=>'۰','1'=>'۱','2'=>'۲','3'=>'۳','4'=>'۴','5'=>'۵','6'=>'۶','7'=>'۷','8'=>'۸','9'=>'۹']);$h=$m->jobs('history',1,'submitted',$fa);ck(in_array($job,array_map('intval',array_column($h['rows'],'id')),true),'old print via Persian digits');$h=$m->jobs('history',1,'submitted','qa-fp2-archive');ck($h['total']===65&&$h['pages']===3&&count($h['rows'])===25,'complete SQL pagination');ck($m->jobs('history',1,'submitted','%')['total']===0,'literal wildcard');});
